#!/usr/bin/env bash
set -euo pipefail
GSZ=/opt/gsz
R="$GSZ/routes/admin.js"; C="$GSZ/views/admin/content.ejs"; A="$GSZ/views/about.ejs"
TS=$(date +%Y%m%d-%H%M%S)
echo "==> step177: About Us editable from admin (/admin/content)"
for F in "$R" "$C" "$A"; do cp "$F" "$F.bak-step177-$TS"; done
echo "    backups: *.bak-step177-$TS"
restore(){ echo "!! restoring"; for F in "$R" "$C" "$A"; do cp "$F.bak-step177-$TS" "$F" 2>/dev/null||true; done; }
trap 'restore' ERR
PATCHER=$(mktemp /tmp/patch_step177.XXXXXX.js)
echo "" | base64 -d > "$PATCHER"
echo "==> applying"; NODE_PATH="$GSZ/node_modules" node "$PATCHER" "$GSZ"
echo "==> validating"
NODE_PATH="$GSZ/node_modules" node --check "$R" && echo "    admin.js ok"
for V in "$C" "$A"; do NODE_PATH="$GSZ/node_modules" node -e "const ejs=require('ejs'),fs=require('fs');ejs.compile(fs.readFileSync('$V','utf8'),{filename:'$V'});console.log('    ejs ok: $V')"; done
echo "==> restarting"; pm2 restart gsz >/dev/null 2>&1 || pm2 restart gsz
CODE=000; for i in $(seq 1 25); do sleep 1; CODE=$(curl -s -o /dev/null -w '%{http_code}' http://127.0.0.1:3900/about || echo 000); [ "$CODE" = "200" ] && break; done
[ "$CODE" = "200" ] || { echo "    /about $CODE"; false; }
echo "    /about 200: OK (after ${i}s)"
rm -f "$PATCHER"; trap - ERR
echo ""
echo "==> step177 OK  Admin > Content now has an 'About Us page' box. Write your About Us there and Save — it shows on /about immediately. Leave it empty to keep the default text."
